"Abstand Anfang / Ende":"起点 / 终点距离",
"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"起点 / 终点距离可将折边变为局部折边。草图中的其他封闭轮廓将成为板上的切口。折边上的孔和窗口：沿边线的中心（弯曲边线则沿圆弧）、距折弯末端的中心、尺寸——它们也会出现在展开图中。若弯曲边线无折角地过渡到相邻边线，且两者的折边折弯角相同，则两个折边无止裂槽地连成一体。“来自草图的轮廓”将某个草图的封闭轮廓从折边上切除：草图的 X 沿边线方向，Y 指向折边内，原点位于边线起点处的折弯末端（可移动）。",
