"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"选择所有要消失的面（型腔选侧壁和底面，孔选孔壁，圆角选圆角面）。相邻面会延伸并填补缺口。实体更改时此步骤会随之重新计算；首次使用时需加载完整几何内核（几秒钟）。",
