"Dafür braucht es zwei bewegliche Gelenke (z. B. zwei Drehgelenke für Zahnräder, Dreh- und Schiebegelenk für Zahnstange und Ritzel).":"这需要两个可动联接（例如齿轮用两个旋转联接，齿条与小齿轮用一个旋转联接和一个滑动联接）。",
