"Ein Exzenter hebt den Stößel um 2 · e und senkt ihn wieder (Hub = 2 · Exzentrizität). Rast: so viel der Umdrehung bleibt der Stößel unten (0 … 0,95).":"偏心轮将推杆抬升 2 · e 后再放下（行程 = 2 · 偏心距）。停歇：推杆在最低位置停留的旋转比例（0 … 0,95）。",
"Ein Lochfeld im geschlossenen Profil der Skizze; Ausschnitte im Profil bleiben frei.":"在草图封闭轮廓内生成孔阵列；轮廓内的切口保持空缺。",
