"Ein geschlossenes Netz in einen Volumenkörper umwandeln (jedes Dreieck wird eine Fläche)":"将封闭网格转换为实体（每个三角形成为一个面）",
"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"圆形铣刀会在每个内角留下其半径 – 带直角的配合件就无法装入。清角会在每个尖锐内角处短暂切入角部再退回。{0}{1}",
"Ein verbundener Agent arbeitet am geöffneten Entwurf: Er liest und ändert die Zeitachse, fragt Körper, Volumen und Fehler ab, holt Normteile aus dem Bauteilkatalog, lässt sich ein Bild der Ansicht geben, exportiert STEP oder STL, legt Werkzeuge und Fertigungsoperationen an und gibt das NC-Programm aus – das vor dem ersten Schnitt zu prüfen bleibt. Auf Dateien, Einstellungen und andere Entwürfe hat er keinen Zugriff. Jede Änderung ist ein Schritt, den Strg+Z zurücknimmt.":"已连接的智能体在当前打开的设计上工作：读取并修改时间轴，查询实体、体积和错误，从零件目录取用标准件，获取视图图片，导出 STEP 或 STL，创建刀具和加工工序并输出 NC 程序——首次切削前仍须验证该程序。它无法访问文件、设置或其他设计。每次更改都是一步，可用 Ctrl+Z 撤销。",
"Ein zweiter Klick auf die Schaltfläche des Zeichenwerkzeugs schaltet zurück auf Auswählen":"再次单击绘图工具按钮即切换回选择",
"Ein-/Ausblenden":"显示/隐藏",
"Ein-/Ausfahrten und Übergänge":"切入/切出和过渡",
"Einblenden":"显示",
