"Eine Bahn entlang jeder Innenecke/Hohlkehle, in der das Werkzeug zwei Flächen zugleich berührt – zum Ausräumen nach dem Schlichten.":"沿刀具同时接触两个面的每个内角/凹圆角走一条刀路 – 用于精加工后的清根。",
"Eine Fläche aus geraden Linien, die von den Kanten aus in die gewählte Richtung laufen.":"由直线构成的曲面，直线从边出发沿所选方向延伸。",
"Eine Fläche, Bohrung oder einen Zapfen anklicken.":"单击面、孔或凸台。",
"Eine Fläche, Bohrung oder einen Zapfen eines Körpers anklicken.":"单击实体的面、孔或凸台。",
"Eine Fläche, die zwei Kanten (oder Kantenzüge) verbindet.":"连接两条边（或边链）的曲面。",
"Eine Konfiguration merkt sich die Ausdrücke aller Parameter unter einem Namen – etwa „kurz“ und „lang“. Ein Klick stellt die Variante wieder her.":"配置以一个名称记住所有参数的表达式——例如“短”和“长”。单击即可恢复该变体。",
"Eine Kunststoffregel legt Wandstärke, Formschräge, Mindestradius und Verhältnisse für Rippen und Dome fest. Zugewiesen an einen Körper gibt sie die Vorgaben für Schale, Rippe, Gewebe und Ansatz; „Konstruktion prüfen“ meldet Abweichungen.":"塑料规则定义壁厚、拔模、最小圆角半径以及加强筋和凸台的比例。将其指定给实体后，会为抽壳、加强筋、筋板和凸台提供默认值；“设计检查”会报告偏差。",
"Eine Platte auf dem offenen Ende eines Rohrs oder Profils, mit dessen Außenkontur (Einzug macht sie kleiner).":"在管材或型材开口端放置一块板，外轮廓与其一致（内缩可使其变小）。",
"Eine Regel legt Blechdicke, Biegeradius und K-Faktor fest. Im Blech wird sie in der Liste „Blechregel“ gewählt.":"规则定义板厚、折弯半径和 K 因子。在钣金件中，可从“钣金规则”列表中选择。",
"Eine Seite":"单侧",
"Eine Starrgruppe braucht mindestens zwei Körper.":"刚性组至少需要两个实体。",
"Eine Umdrehung des Ritzels schiebt die Zahnstange um π · d.":"小齿轮每转一圈，齿条移动 π · d。",
"Eine Umdrehung schiebt die Mutter um die Steigung.":"每转一圈，螺母移动一个导程。",
"Eine Wand entlang der Innenseite des geschlossenen Profils – Auflage für eine Platine oder einen Deckel.":"沿封闭轮廓内侧生成的一道壁——用于承托电路板或盖板。",
