"Eine federnde Zunge mit Rasthaken. Der Haken steht zur Seite +X der Zunge; Drehung dreht ihn um die Richtung.":"带卡钩的弹性舌片。卡钩朝向舌片的 +X 侧；旋转可使其绕方向转动。",
