"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"请先选择草图或构造平面——然后 Ctrl+8 会正对它观察。",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"请先在“设计”中创建实体或插入网格(STL)。",
