"Fläche anklicken: an jedem Klickpunkt entsteht die Durchgangsbohrung für die Schraube (ISO 273, Reihe mittel) durch alle Teile, die dort aufeinanderliegen – für Senkschrauben mit 90°-Senkung, für Zylinderschrauben auf Wunsch mit Senkbohrung (DIN 974-1, Reihe 1) so tief wie der Kopf. Die Schraube sitzt gleich darin. Bohrung und Schraube lassen sich danach im Verlauf ändern.":"点击平面：在每个点击位置生成螺钉的通孔（ISO 273，中等系列），贯穿该处叠放的所有零件——沉头螺钉带 90° 锥形沉孔，圆柱头螺钉可选与头部等深的柱形沉孔（DIN 974-1，系列 1）。螺钉随即装入其中。孔和螺钉之后可在时间轴中修改。",
"Fläche anpassen":"拟合曲面",
"Fläche anpassen: eine Freiformfläche durch die Punkte einer Punktwolke legen":"拟合曲面：让自由曲面通过点云中的各点",
"Fläche begradigen":"拉直面",
"Fläche begradigen: eine Fläche durch eine ruhige Fläche über ihrem Rand ersetzen":"拉直面：用跨越其边界的平顺曲面替换该面",
"Fläche cm²":"面积 cm²",
"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"单击实体的面：其边界将作为轮廓加入草图。单击边则只投影该边（圆仍为圆）。投影几何图元显示为紫色。",
"Fläche ersetzen":"替换面",
"Fläche ersetzen: eine ebene Fläche auf eine andere Ebene legen – der Körper wächst oder wird gekürzt":"替换面：将一个平面移到另一个平面上 – 实体随之加长或缩短",
"Fläche extrudieren":"拉伸面",
"Fläche hinter den Fenstern – gilt, wenn oben das Design „Eigenes“ gewählt ist":"窗口后面的区域——当上方选择“自定义”主题时生效",
"Fläche löschen":"删除面",
"Fläche löschen: Bohrungen, Taschen, Verrundungen oder Fasen entfernen – die Nachbarflächen schließen die Lücke":"删除面：移除孔、型腔、圆角或倒角 – 相邻面封闭缺口",
"Fläche mit Loch":"带孔的面",
