"Fläche teilen":"分割面",
"Fläche teilen: Trennkante entlang einer Ebene oder Skizze, der Körper bleibt ein Stück":"分割面：沿平面或草图生成分割边，实体仍为一体",
"Fläche versetzen":"偏移面",
"Fläche versetzen: ebene Flächen verschieben, Bohrungen und Zapfen im Durchmesser ändern":"偏移面：移动平面，更改孔和凸柱的直径",
"Fläche wählen":"选择面",
"Fläche wählen, die getrimmt wird":"选择要修剪的曲面",
"Fläche zum Antasten in Z":"Z 向探测的面",
