"Für schräge Richtungen eine Konstruktionsachse anlegen (durch zwei Punkte, einen Zylinder oder zwei Ebenen) – sie erscheint dann hier als Richtung.":"对于倾斜方向，请创建构造轴(通过两点、一个圆柱或两个平面) – 它随后会作为方向显示在此处。",
