"Gemeinsame Schnittkanten nur einmal schneiden":"共用切割边只切一次",
"Gemeinsame Schnittkanten: liegen zwei Zuschnitte genau eine Schnittfuge auseinander (beim Schachteln als Abstand die Schnittfuge eintragen), fällt ihre Bahn auf der gemeinsamen Kante zusammen und wird nur einmal geschnitten. Der Anschnitt liegt nie in einem Nachbarteil: ist neben einer Kontur kein freier Abfall, wird auf der Kontur eingestochen. Nach „Vorschau“ zeigt ein Bild je Tafel die Bahn, bevor die Dateien gespeichert werden.":"共用切割边：若两个下料件恰好相距一个切缝（排样时把间距设为切缝宽度），它们在共用边上的路径重合，只切一次。引入线绝不会落在相邻零件内：若轮廓旁没有空余废料，则直接在轮廓上穿孔。点击“预览”后，在保存文件之前会按每张板显示路径图。",
