"Gerade":"直线",
"Gerade (radial)":"直线（径向）",
"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"草图中不属于任何轮廓的直线（包括构造线）。折弯：该线是折弯区的中线，草图在此处即为下料图——板的最大一块保持不动，线另一侧的部分连同其折边一起转动。该线对整块板有效。加强筋：沿该线的一条凸筋，截面和两端均为圆形；板厚保持不变。",
"Gerade Nuten (Langloch oder Linie mit Nutbreite) gehen als Nutzyklus der Steuerung heraus.":"直槽（长槽或带槽宽的直线）将作为数控系统的槽循环输出。",
