"Geschlossen (Gehrung)":"闭合（斜接）",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"闭合：相邻两条边上的折边延伸到拐角的角平分线，并在那里留出间隙。拐角止裂槽位于折弯区相交处——在展开图和折弯件中均如此。弯曲边线上的折边在真正的拐角处同样按斜接切割（该处没有拐角止裂槽）。",
"Geschlossene Hohlräume im Inneren des Körpers werden mit Material gefüllt.":"实体内部的封闭空腔将被材料填充。",
