"Geschlossene Profile werden zu ebenen Flächen – z. B. Deckel und Boden, um Flächen anschließend zu einem Körper zusammenzufügen.":"闭合轮廓将变为平面曲面 – 例如顶盖和底面，以便随后将曲面缝合成实体。",
