"Gespeichert werden Blechdicke {0} mm, Biegeradius innen {1} mm und K-Faktor {2}. Die Regel steht danach bei jedem Blech in der Liste „Blechregel“ – auch in anderen Projekten auf diesem Rechner.":"将保存板厚 {0} mm、内弯曲半径 {1} mm 和 K 系数 {2}。之后该规则会出现在每个钣金件的“钣金规则”列表中——也包括本机上的其他项目。",
