"Gestrichelt im DXF/der Skizze: Biegelinien (Anfang und Ende jeder Biegezone). Im DXF liegen sie auf der Ebene BIEGUNG, der Umriss auf Ebene 0.":"DXF/草图中的虚线：折弯线（每个折弯区的起点和终点）。在 DXF 中它们位于图层 BIEGUNG，轮廓位于图层 0。",
