"Gewinde als ein Zyklus-Satz: Okuma G71 (gerade Zustellung B0, Gewindetiefe H, erste Zustellung D), Fanuc G76 (Flankenzustellung 60°).":"螺纹作为一个循环程序段：Okuma G71(直进式进刀 B0，螺纹深度 H，首次切深 D)，Fanuc G76(侧面进刀 60°)。",
