"Gewindebohrung im untersten Teil":"最下面的零件中加工螺纹孔",
"Gewindebohrung im untersten Teil: die Durchgangsbohrung endet, wo das unterste Teil beginnt; dort entsteht das Kernloch mit Gewinde – drei Gewindegänge tiefer, als die Schraube reicht, oder durch das ganze Teil. Liegt nur ein Teil unter dem Punkt, bekommt es das Gewinde von der Fläche an. „Länge passend zur Einschraubtiefe“ nimmt die nächste Länge der Reihe, mit der die Schraube etwa so tief im Gewinde sitzt, wie ihr Gewinde dick ist (Richtwert für Stahl) – aber nie länger, als das Teil dick ist.":"最下面的零件中加工螺纹孔：通孔在最下面的零件开始处结束；在那里生成带螺纹的底孔——比螺钉到达的深度深三个螺距，或贯穿整个零件。若该点下方只有一个零件，则从其表面起加工螺纹。“长度按旋入深度选取”会取系列中的下一个长度，使螺钉旋入螺纹的深度约等于其螺纹直径（钢材的参考值）——但绝不超过零件的厚度。",
"Gewindebohrung {0} – Einschraubtiefe nur {1} mm":"螺纹孔 {0} – 旋入深度仅 {1} mm",
