"Gewindebohrung: gebohrt wird das Kernloch; das Gewinde erscheint als Gewindedarstellung am Modell und mit seinem Namen in der Zeichnung.":"螺纹孔：钻出的是底孔；螺纹在模型上以装饰螺纹显示，并在工程图中标注其名称。",
