"Gleiche Durchmesser ergeben ein Rohr, verschiedene einen Kegelstumpf. Die Abwicklung wird auf der neutralen Faser gerechnet (Innenfläche + K-Faktor × Blechdicke); beim Runden liegt sie näher an der Blechmitte als beim Abkanten – üblich ist ein K-Faktor von 0,45 bis 0,5. Mit einer Blechregel gelten deren Dicke und K-Faktor. Der Nahtspalt bleibt am größeren Durchmesser offen (0 = stumpf gestoßen, im Körper dann ein Schlitz von 0,01 mm).":"直径相同得到圆筒，不同则得到圆锥台。展开图按中性层计算（内表面 + K 系数 × 板厚）；卷圆时中性层比折弯时更靠近板厚中面——通常 K 系数为 0.45 至 0.5。选用钣金规则时采用其板厚和 K 系数。接缝间隙留在较大直径处（0 = 对接，实体中则为 0.01 mm 的缝）。",
