"Gleichmäßige Dreiecke dieser Größe: lange Kanten werden geteilt, danach wird auf die Dreieckszahl eines gleichmäßigen Netzes reduziert. Gut vor dem Glätten oder Formen von Scans.":"生成该尺寸的均匀三角形：先分割较长的边，再缩减到均匀网格的三角形数量。适合在对扫描数据进行平滑或造型之前使用。",
