"Halbzeug: Nennmaße der Norm, auf jede Länge zugeschnitten. Nicht jede Paarung von Maß und Wanddicke ist bei jedem Händler am Lager. Ein Rohr entlang einer Skizzenlinie – auch um Ecken und Bögen – legt der Befehl „Rohr“ an.":"型材：标准的公称尺寸，可切成任意长度。并非每种尺寸与壁厚的组合在每家供应商处都有库存。沿草图线（包括拐角和圆弧）的管由“管道”命令创建。",
