"Heidenhain: an der Steuerung die Datenübertragung über Ethernet freigeben (wie für TNCremo, LSV2, Port 19000); Standardordner TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: Port 21, Ordner z. B. /_N_WKS_DIR oder /NC. Netzwerkordner: Pfad wie \\\\MASCHINE\\NC oder Z:\\NC. DNC: Wandler als TCP-Server (raw), meist Port 4001; an der Steuerung „Abarbeiten extern“, DNC oder TAPE starten.":"Heidenhain：在数控系统上启用以太网数据传输（与 TNCremo、LSV2 相同，端口 19000）；默认文件夹 TNC 640 TNC:\\nc_prog\\，iTNC 530 TNC:\\。FTP：端口 21，文件夹例如 /_N_WKS_DIR 或 /NC。网络文件夹：路径如 \\\\MASCHINE\\NC 或 Z:\\NC。DNC：转换器作为 TCP 服务器（raw），通常端口 4001；在数控系统上启动“外部运行”、DNC 或 TAPE。",
