"Im Spiegelbild läuft das Werkzeug andersherum: aus Gleichlauf wird dort Gegenlauf. Die Radiuskorrektur der Steuerung wechselt die Seite mit.":"在镜像中刀具反向运行：顺铣在该处变为逆铣。数控系统的刀具半径补偿也随之换侧。",
