"Importierte Körper sind ohne Konstruktionshistorie, lassen sich aber weiterbearbeiten (Verrundung, Fase, Ausschneiden …) und für CAM verwenden. Mit „Y-Achse oben“ werden Modelle aus Programmen mit Y nach oben richtig hingestellt.":"导入的实体没有设计历史，但可以继续编辑（圆角、倒角、剪切 …）并用于 CAM。使用“Y 轴向上”可将来自 Y 轴朝上的软件的模型正确摆放。",
