"JSON kopieren":"复制 JSON",
"Je Operation zwei Q-Parameter am Programmanfang: der erste verschiebt die Tiefe (DL, + = weniger tief), der zweite das seitliche Aufmaß (DR, + = mehr Aufmaß; wirkt nur bei Radiuskorrektur an der Steuerung RL/RR). An der Maschine eine Zahl ändern statt Sätze suchen.":"每个操作在程序开头有两个 Q 参数：第一个偏移深度（DL，+ = 更浅），第二个偏移侧面余量（DR，+ = 更多余量；仅在数控系统半径补偿 RL/RR 时有效）。在机床上只需改一个数，无需查找程序段。",
"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"每个草图取第一条曲线 – 开放或闭合均可。这些曲线由一张蒙皮连接（无厚度的曲面）。",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Kiemenschlitze werden auf ihrer Linie geschnitten. Haltestege: so viele Stellen je Umriss bleiben stehen (Laser, Plasma, Wasserstrahl: der Strahl setzt dort aus; Fräsen: der Fräser hebt auf halbe Blechdicke), Umrisse unter 40 mm Länge bekommen keine. „Steuerung“ legt fest, womit der Strahl ein- und ausgeschaltet wird; die Einstechzeit steht als G4 im Programm, außer die Steuerung sticht selbst ein. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"每张板一个文件。路径在废料一侧偏离轮廓半个切缝（铣削时为半个刀具直径）；内孔先于所属零件的外轮廓切割，每条轮廓都从废料处引入。百叶窗切缝沿其线切割。连接桥：每个外轮廓保留相应数量的位置不切断（激光、等离子、水刀：光束在该处中断；铣削：刀具抬到板厚的一半），长度小于 40 mm 的轮廓不设连接桥。“控制系统”决定光束开关所用的指令；穿孔时间以 G4 写入程序，除非控制系统自行穿孔。原点为板的左下角，铣削时 Z0 为板的上表面。使用前请在机床上或 NC 仿真器中验证程序。",
"Je Werkzeug alle Teile (weniger Werkzeugwechsel)":"每把刀具加工所有零件（换刀更少）",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"各轴单独设置：单击边、角点、面或孔。未设置的轴取自毛坯点。",
"Jede Bohrung wird mit ihren Koordinaten einzeln angefahren (X/Y je Bohrung) – kein Lochkreis- oder Rastermuster.":"每个孔按各自坐标逐一定位（每孔 X/Y）– 不使用分布圆或栅格图案。",
"Jede Fläche des Körpers wird ein eigener Flächenkörper.":"实体的每个面都成为独立的曲面体。",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"每个工序作为子程序(LBL)放在程序末尾，用 CALL LBL 调用",
"Jede offene Linie der Skizze wird zu einer Rippe – ein ganzes Rippennetz in einem Schritt.":"草图中的每条开放线都会变成一条筋——一步生成整个筋网。",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"草图中的每个圆都是一个孔中心。钻孔方向与草图法向相反（进入材料）。",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"草图中的每个圆绕中心（草图坐标）旋转复制——位于分度圆半径处的一个圆即可得到螺栓圆。",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"草图中的每个圆都生成一个栅格：间距沿草图的 X 和 Y 方向（可为负值）。",
"Jeder Körper in einer eigenen Farbe":"每个实体使用各自的颜色",
"Jeder sichtbare Körper wird ein Glied mit Netz (STL, in Metern), Masse und Trägheit, jedes Gelenk ein Gelenk mit Achse und Grenzen. Die jetzige Stellung ist die Nullstellung. Mit einem Paketnamen stehen die Netze im URDF als package://Name/meshes/…, sonst als relativer Pfad.":"每个可见实体成为一个连杆，带网格（STL，单位为米）、质量和惯量；每个关节成为带轴线和限位的关节。当前姿态为零位。填写功能包名称后，URDF 中的网格写作 package://Name/meshes/…，否则使用相对路径。",
"Jedes # im Skizzentext wird durch die Nummer ersetzt, mit Nullen aufgefüllt (SN-#### → SN-{0}). Bei mehreren Teilen in einer Aufspannung bekommt jedes Teil die nächste Nummer: {1}{2}.":"草图文本中的每个 # 都替换为编号，并以零补齐（SN-#### → SN-{0}）。一次装夹多个零件时，每个零件获得下一个编号：{1}{2}。",
"Jedes Teil hat seinen eigenen Nullpunkt in der Steuerung (G54, G55 … bzw. Bezugspunkt-Nummer in der Tabelle – Heidenhain Zyklus 247). Alle Nullpunkte vorher an der Maschine setzen.":"每个零件在数控系统中有自己的工件坐标系（G54、G55 … 或表中的预设点编号 – Heidenhain 循环 247）。请事先在机床上设定所有原点。",
"Jedes eigene Maß und jeder Toleranzrahmen bekommt eine Nummer in einem Kreis. Die Liste enthält Nennmaß, Toleranz, Höchst- und Mindestmaß und Felder für den Istwert. Maße ohne eigene Toleranz bekommen die Allgemeintoleranz.":"每个自有尺寸和每个公差框格都会获得一个圆圈编号。列表包含公称尺寸、公差、最大和最小尺寸以及实测值栏。没有自身公差的尺寸采用一般公差。",
