"KI-Agenten verbinden sich mit der Desktop-App von WerkFab (Windows, Linux, macOS) über das Model Context Protocol (MCP). Im Browser gibt es dafür keinen Anschluss.":"AI 代理通过模型上下文协议（MCP）连接 WerkFab 桌面应用（Windows、Linux、macOS）。浏览器中没有此接口。",
