"Kalibrieren: zwei Punkte im Bild anklicken, deren Abstand bekannt ist, und den wirklichen Abstand eingeben – das Bild bekommt den richtigen Maßstab.":"校准：在图像中单击距离已知的两点，并输入实际距离 – 图像即获得正确的比例。",
