"Kante am bewegten Körper gewählt":"已选择移动实体上的边",
"Kante im Blatt anklicken …":"在图纸上单击边 …",
"Kante projiziert":"边已投影",
"Kante {0} (Bogen R{1}, {2} mm)":"边 {0}（圆弧 R{1}，{2} mm）",
"Kante {0} (Kreis R{1}, {2} mm)":"边 {0}（圆 R{1}，{2} mm）",
"Kante {0} ({1} mm)":"边 {0} ({1} mm)",
"Kante {0} ist zu kurz für eine Lasche":"边 {0} 太短，无法创建凸缘",
"Kante {0}: Biegewinkel über 180° ist nicht herstellbar.":"边 {0}：超过 180° 的折弯角无法制造。",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"边 {0}：曲线边上的折边 – 成形时其边缘被压缩 {1} %（有起皱风险）；该处的展开料为近似值。",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"边 {0}：曲线边上的折边 – 成形时其边缘被拉伸 {1} %（有开裂风险）；该处的展开料为近似值。",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"边 {0}：折边尺寸 {1} mm 小于折弯（{2} mm）",
"Kante {0}: der Bogen ist zu eng für diese Lasche":"边 {0}：圆弧对该折边来说太小",
"Kante {0}: die Abstände lassen keine Lasche übrig.":"边 {0}：这些距离没有留下折边。",
"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"边 {0}：折边与折弯线相交——请用“起点 / 终点距离”让它在折弯前结束",
"Kante {0}: die Lasche liegt in einer Biegezone":"边 {0}：折边位于折弯区内",
"Kante {0}: ein Ausschnitt gehört zu einer Lasche, die es nicht gibt.":"边 {0}：有切口属于不存在的折边。",
"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"边 {0}：折边上有切口距折弯处 {1} mm（小于 2 × 板厚）– 折弯时会变形。",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"边 {0}：有切口距折弯处 {1} mm（小于 2 × 板厚）– 折弯时会变形。",
"Kante {0}: ein Ausschnitt ragt über die Lasche hinaus.":"边 {0}：有切口超出了折边。",
"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"边 {0}{1}：折边 {2} mm 短于 2 × 板厚 – 在折弯机上几乎无法折弯。",
"Kante {0}{1}: Saum {2} mm ist kürzer als 4 × Blechdicke – er lässt sich schlecht zudrücken.":"边 {0}{1}：折边 {2} mm 短于 4 × 板厚——难以压合。",
"Kante {0}{1}: geschlossener Saum (Innenradius {2} mm) – wird in zwei Hüben gebogen und zugedrückt; harte Werkstoffe reißen dabei an der Außenseite.":"边 {0}{1}：闭合折边（内半径 {2} mm）——需分两次行程折弯并压合；硬质材料外侧会因此开裂。",
"Kante: {0} · Länge {1} mm":"边：{0} · 长度 {1} mm",
"Kanten":"边",
"Kanten (Geraden deckungsgleich, Kreise mittig)":"边(直线重合，圆同心)",
"Kanten anklicken (erneut klicken entfernt).":"单击边(再次单击取消选择)。",
"Kanten anklicken zum Hinzufügen oder Entfernen – das Ergebnis erscheint gleich im Modell. Kanten, die vor dem Befehl angeklickt wurden, sind schon gewählt. Eingabe = OK.":"点击边即可添加或移除，结果会立即显示在模型中。在执行命令之前点击的边已被选中。Enter = 确定。",
