"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"轮廓沿深色区域的边界生成。中心线沿笔画的中间生成 – 适用于雕刻和线条图。“直线、圆弧和圆”可识别直边、尖角、圆角和圆；“多段线”逐点跟随图像。之后可根据需要用“校准参考图像”或“缩放”调整比例。",
