"Lasche an Lasche: Winkel + biegt in dieselbe Richtung weiter (U-Profil, Falz mit 180°), − in die Gegenrichtung (Z-Stufe, Hutprofil). Saum: der Rand der Lasche wird um 180° auf sich selbst zurückgelegt – offen mit einem Spalt von einer Blechdicke, geschlossen flach zugedrückt; mit − 180° liegt er auf der anderen Seite. Das Feld R ist der Innenradius nur dieser Biegung (leer = wie beim Blech). Für einen Saum direkt an der Plattenkante die Lasche selbst auf 180° stellen. Kröpfung: zwei Biegungen gegeneinander (− 45° und + 45°) – der Rand läuft parallel versetzt weiter; Versatz über die Länge des schrägen Stücks und die Winkel.":"折边上的折边：角度为 + 时沿同一方向继续折弯（U 形件、180° 折叠），为 − 时反向折弯（Z 形台阶、帽形件）。折边：将翻边的边缘向自身折回 180°——开口式留一个板厚的间隙，闭合式压平；用 − 180° 时位于另一侧。字段 R 仅是此折弯的内半径（留空 = 与钣金件相同）。若要直接在板边上做折边，将翻边本身设为 180°。错位折弯：两道方向相反的折弯（− 45° 和 + 45°）——边缘平行错开后继续延伸；错开量由斜段长度和角度决定。",
"Lasche {0}":"折边 {0}",
