"Macht ein geschlossenes Netz hohl: eine Innenwand im Abstand der Wandstärke kommt dazu – spart Material und Druckzeit. Stellen, die dünner sind als zwei Wandstärken, überschneiden sich danach; für Harzdruck ein Ablaufloch mit „Boolesch“ abziehen.":"将封闭网格掏空：在相距壁厚的位置增加一层内壁，可节省材料和打印时间。比两倍壁厚更薄的位置之后会相互重叠；用于树脂打印时，请用“布尔运算”减去一个排液孔。",
