"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"多条相连的边视为一段路径：半径从链的起点延续到终点，控制点按整条链长度的 % 计算。由完整几何内核计算。",
"Mehrfachaufspannung":"多件装夹",
"Mehrfachaufspannung: Nullpunkt von Teil {0} gibt es an dieser Steuerung nicht – nur ein Teil ausgegeben":"多件装夹：此数控系统没有零件 {0} 的工件坐标系 – 仅输出一个零件",
"Mehrfachaufspannung: Nullpunktverschiebung gibt es in diesem Postprozessor nicht – „Eigener Nullpunkt je Teil“ wählen; nur ein Teil ausgegeben":"多件装夹：此后处理器不支持原点偏移 – 请选择“每个零件单独的工件坐标系”；仅输出一个零件",
"Meine Designs · {0}":"我的设计 · {0}",
"Meine Werkzeuge":"我的刀具",
"Meldet Bahnen, die tiefer schneiden als das Modell an dieser Stelle (Schaft-, Plan-, Kugel- und Torusfräser, Fasenfräser und Bohrer mit ihrem Kegel; 3-Achs-Bewegungen). Ein Schnitt, der nicht im Modell steht – Gravur, Eckenfreistich, Tasche nur aus einer Skizze – wird ebenfalls gemeldet.":"报告切削深度超过该处模型的刀路（立铣刀、面铣刀、球头铣刀和圆鼻铣刀，倒角铣刀和钻头按其锥形计算；三轴运动）。模型中没有的切削——雕刻、角部让刀、仅由草图生成的型腔——同样会被报告。",
"Meldung auf dem Bildschirm der Steuerung: Fanuc und LinuxCNC als (MSG, …), Sinumerik als MSG(\"…\"), sonst als Kommentar.":"数控系统屏幕上的消息：Fanuc 和 LinuxCNC 为 (MSG, …)，Sinumerik 为 MSG(\"…\")，其他为注释。",
