"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP：G28/G53 在该系统上不移动到机床坐标(G53 会取消刀具长度补偿) – 退刀至安全高度，不输出 XY 回零",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP：未输出平滑功能(G5.1 属于 Fanuc) – 请在机床上设置 Hi-Cut/Super-NURBS",
"Okuma: Korrektur+Werkzeug+Schneide (z. B. 010101)":"Okuma:补偿+刀具+刀刃(例如 010101)",
"OpenCascade (alle Funktionen)":"OpenCascade(全部功能)",
"OpenCascade: alle Funktionen. Rust-Kern (truck, experimentell): Grundkörper, Extrusion, Rotation, Bohrung, Muster, Spiegeln, Verschieben, Skalieren, Kombinieren und STEP-Export – andere Features werden als „noch nicht unterstützt“ markiert.":"OpenCascade：全部功能。Rust 内核(truck，实验性)：基本体、拉伸、旋转、孔、阵列、镜像、移动、缩放、合并和 STEP 导出 – 其他特征将标记为“尚不支持”。",
