"Prägung: die Kontur wird nicht ausgeschnitten, sondern um die Höhe aus der Platte gedrückt; das zweite Feld ist die Wandschräge (0° = senkrecht). Senkprägung: der Rand einer runden Bohrung wird zu einem 90°-Kegel gedrückt – für Senkschrauben in dünnem Blech (− nach unten: Schraube von oben).":"压印：轮廓不被切除，而是按高度从板中压出；第二个输入框是壁面斜度（0° = 垂直）。沉孔压印：圆孔边缘被压成 90° 锥面——用于薄板上的沉头螺钉（− 向下：螺钉从上方装入）。",
