"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"由沿车削轴线放置的草图的闭合轮廓生成圆周上的型腔（内部轮廓保留为岛屿）。草图被包覆到直径上；指向轴线的动力平底立铣刀由内向外清除（Z 和 C 联动；Fanuc：圆柱插补 G7.1）。刀具沿最内圈以斜坡方式下刀。",
"Tasche gespiegelt":"镜像凹槽",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"根据草图的封闭轮廓在端面上加工型腔(内部轮廓保留为岛屿)，使用动力平底立铣刀沿 Z 加工。由内向外清除；铣刀沿最内侧路径斜插下刀，并在同一层内保持在下方。X 和 C 联动(Fanuc：极坐标插补 G12.1)。深度自端面起算。",
"Tasche mit Insel":"带岛屿的型腔",
"Tasche mit Insel – der Steuerungszyklus kann keine Inseln":"型腔带岛屿 – 系统固定循环不支持岛屿",
