"Tauchschruppen braucht ein Werkzeug mit flacher Stirn (Schaft-, Plan- oder Tauchfräser)":"插铣粗加工需要端面平直的刀具（立铣刀、面铣刀或插铣刀）",
"Tauchschruppen: senkrechte Tauchgänge Reihe für Reihe – für lange Werkzeuge und tiefe Kavitäten":"插铣粗加工：逐行垂直插铣 – 适用于长刀具和深型腔",
"Teil 1 liegt normalerweise auf dem Nullpunkt (0, 0, 0). Die anderen werden mit einer Nullpunktverschiebung angefahren (Heidenhain Zyklus 7, Fanuc/LinuxCNC G52, Sinumerik TRANS). Vor jedem Wechsel geht das Werkzeug auf die sichere Höhe.":"零件 1 通常位于原点 (0, 0, 0)。其他零件通过原点偏移到达（Heidenhain 循环 7、Fanuc/LinuxCNC G52、Sinumerik TRANS）。每次切换前刀具先退到安全高度。",
