"Teilt Kanten, die länger sind, in der Mitte (je Durchgang einmal) – die Form bleibt gleich. 0 teilt jede Kante: jedes Dreieck wird zu vier. Sinnvoll vor dem Glätten grober Netze.":"在中点分割较长的边（每遍一次）——形状保持不变。0 表示分割每条边：每个三角形变为四个。适合在平滑粗糙网格之前使用。",
