"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"对两个封闭网格进行真正的布尔运算：内部的面会消失，相交边会重新划分网格。只计算两个网格可能相遇的区域 – 因此大网格上的小改动很快。若两个大网格完全重叠，请先“简化”。",
