"Verschleiß":"磨损",
"Verschraubung: Scheiben und Mutter kommen mit der Schraube in einem Zug an jede angeklickte Bohrung. Die Klemmdicke ist die Länge der Bohrung – durch mehrere Teile hindurch, wenn ihre Bohrungen fluchten und aneinanderstoßen. Mit Mutter wird die kürzeste Vorzugslänge vorgeschlagen, bei der die Schraube zwei Gewindegänge aus der Mutter ragt.":"螺栓连接：垫圈和螺母随螺钉一次装到每个点击的孔上。夹紧厚度即孔的长度——若多个零件的孔同轴且相接，则贯穿这些零件。带螺母时，建议采用螺钉伸出螺母两个螺距的最短优选长度。",
