"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"将草图曲线缠绕到圆柱上：X 保持为 X，垂直于轴线的距离变为展开Ø上的圆弧(A 轴旋转)。草图必须平行于 A 轴，例如位于切平面上。在零件表面以下的固定深度铣削 – 用于环绕零件的雕刻、文字和槽。",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"与3D轮廓相同，但刀具无台阶连续下降 – 陡壁上无下刀痕。",
