"Wie fein Körper für STL, 3MF und den Slicer in Dreiecke zerlegt werden: Abweichung von der wahren Fläche als Anteil der Körpergröße. Netze bleiben, wie sie sind.":"为STL、3MF和切片软件将实体分割成三角形的精细程度：与真实曲面的偏差，以实体尺寸的比例表示。网格保持不变。",
"Wie fein Zylinder, Kugeln und Rundungen in der Ansicht aus Dreiecken bestehen. Feiner sieht runder aus, rechnet bei großen Modellen aber länger. Der Export hat eine eigene Einstellung (3D-Druck).":"视图中圆柱、球体和圆角由三角形划分的精细程度。越精细越圆滑，但大型模型计算更久。导出有单独的设置（3D 打印）。",
