"Zungen stehen am freien Ende der Lasche über und kommen in den Zuschnitt. „Schlitze als Skizze“ legt die passenden Schlitze dort an, wo die Zungen stehen – je Ebene eine Skizze, jeder Schlitz ringsum um das Spiel größer als die Zunge. In dieser Skizze den Umriss des Gegenstücks zeichnen und daraus ein Blech oder eine Extrusion machen: die Schlitze werden Ausschnitte. Das Gegenstück liegt auf den Laschenenden auf; die Zungenlänge ist üblich gleich seiner Dicke.":"榫舌从折边的自由端伸出，并进入展开图。“槽生成草图”在榫舌所在位置创建匹配的槽——每个平面一个草图，每个槽四周比榫舌大一个间隙。在该草图中绘制配合件的轮廓，并由此生成钣金或拉伸：槽成为切口。配合件搁在折边末端；榫舌长度通常等于其厚度。",
