"Zwischen zwei Schnitten hebt das Werkzeug nur so weit ab, wie das Material auf dem Weg es verlangt (Rohteil abzüglich allem, was dieses Setup bis dahin gefräst hat) plus Sicherheitsabstand – und beginnt den Vorschub erst dort.{0}{1}":"两次切削之间，刀具只抬到路径上材料所需的高度（毛坯减去本设置此前已铣掉的部分）再加安全距离，并从那里才开始进给。{0}{1}",
