"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"“相互嵌套排样”会把下料件放进相邻零件的空隙和凹口以及它们的切口中（不允许旋转 90° 时仅翻转 180°）；间距绝不会小于设定值。不勾选时，下料件按其外接矩形成行排列。选择“草图 + 实体”会生成板厚的平板实体，可在加工中用 2D 轮廓切出。",
